import{z as A,x as o,o as B,c as d,q as s,j as i,D as e,d as r,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"BBRv2 / v3","description":"","frontmatter":{"title":"BBRv2 / v3","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bbr-v2-v3.md","filePath":"cs/bbr-v2-v3.md","lastUpdated":1791063341000}'),p={name:"cs/bbr-v2-v3.md"};function C(v,a,D,m,b,h){const t=o("Mermaid");return B(),d("div",null,[a[2]||(a[2]=s('<h1 id="bbrv2-v3" tabindex="-1">BBRv2 / v3 <a class="header-anchor" href="#bbrv2-v3" aria-label="Permalink to &quot;BBRv2 / v3&quot;">​</a></h1><div class="epigraph"><p>BBR 用带宽与 RTT 估计管道，不靠丢包减半；v2/v3 修过估、公平与 ECN 反应，仍在模型与测量之间摇摆。</p><footer>—— 据 Cardwell et al., BBR, ACM Queue 2016；BBRv2/v3 公开设计说明整理</footer></div><p>主干<a href="/cs/bbr">BBR 对照</a> 已给 v1 直觉。<a href="/cs/bufferbloat">缓冲膨胀</a> 是 v1 在深缓冲上的痛。<a href="/cs/quic-migration">上一课</a> 不改控制律。缺口是 <strong>v2/v3 补什么</strong>：带宽过估、与 CUBIC 共存、ECN。本课不把 Vegas 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>v1 ProbeBw 可把队列推高，深缓冲上仍膨胀；对 CUBIC 不公平。v2：更保守的带宽头、对丢失/ECN 作出反应、量化公平。v3 继续调探测与启动。模型：maxBW × minRTT ≈ BDP，窗口绕此值。误码链路把丢当拥塞仍可能，但比 AIMD 少抽空——卫星动机还在。</p><p>不要把版本号写成已在 RFC 终稿冻结；课钉对象与问题。</p><p><span class="marginnote">v1：Cardwell 2016。后续版本以公开幻灯与代码为准，不把未冻结的草案号当标准。</span></p><p><span class="marginnote">直觉类比：v1 像只看导航的司机——自己测路况（带宽与 RTT）决定油门，不因为远处别人追尾（丢包）就急刹；v2/v3 则学会了听到喇叭（ECN 标记、丢包上升）也松一点油门，免得一直压着同路的车。</span></p><h3 id="模型不是-aimd-换皮" tabindex="-1">模型不是 AIMD 换皮 <a class="header-anchor" href="#模型不是-aimd-换皮" aria-label="Permalink to &quot;模型不是 AIMD 换皮&quot;">​</a></h3><p>v1 在深缓冲仍可膨胀。v2/v3 更听丢与 ECN，并修公平。版本以公开设计说明与代码为准，课钉对象不钉某年冻结稿。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 AIMD 相位图 vs BBR 管道估计。画：Probe → Drain → Cruise。与 DCTCP：都利用 ECN，一个比例减，一个进模型。</p><p><span class="marginnote">术语翻译：ECN（Explicit Congestion Notification，显式拥塞通知）就是路由器在包头上盖一枚「快堵了」的章，接收方把这个记号回传给发送端——让它在丢包发生之前就知道减速，比「拿丢失当烟雾报警」早一步。</span></p>',13)),(B(),i(n,null,{default:e(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BW%5B%22%E4%BC%B0%E8%AE%A1%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20BDP%5B%22%E4%B9%98%20minRTT%22%5D%0A%20%20BDP%20--%3E%20CAP%5B%22%E5%B7%A1%E8%88%AA%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SIG%5B%22%E4%B8%A2%2FECN%22%5D%20--%3E%20V2%5B%22v2%20%E6%9B%B4%E5%90%AC%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"QUIC 与 Linux TCP 都有实现。多路径下每条路径一套估计。AQM 浅队列让 minRTT 更真。P4 不实现 BBR，BBR 在端。RoCE 用 DCQCN 不是 BBR。",-1)),a[5]||(a[5]=E("p",null,"过估：把突发当可用带宽，会伤同队列邻居——v2 要压这点。",-1)),(B(),i(n,null,{default:e(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20V1%5B%22v1%20%E7%9A%84%E9%97%AE%E9%A2%98%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20A%5B%22%E7%AA%81%E5%8F%91%E8%A2%AB%E5%BD%93%E6%88%90%E5%8F%AF%E7%94%A8%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20B%5B%22%E5%B8%A6%E5%AE%BD%E8%BF%87%E4%BC%B0%2C%20%E7%AA%97%E5%8F%A3%E5%81%8F%E5%A4%A7%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E9%98%9F%E5%88%97%E8%A2%AB%E6%8E%A8%E9%AB%98%2C%20%E5%90%8C%E9%98%9F%E9%82%BB%E5%B1%85%E5%8F%97%E5%8E%8B%22%5D%0A%20%20end%0A%20%20subgraph%20V2V3%5B%22v2%20%2F%20v3%20%E7%9A%84%E8%A1%A5%E4%B8%81%22%5D%0A%20%20%20%20D%5B%22%E6%9B%B4%E4%BF%9D%E5%AE%88%E7%9A%84%E5%B8%A6%E5%AE%BD%E4%B8%8A%E9%99%90%22%5D%20--%3E%20E%5B%22%E5%AF%B9%E4%B8%A2%E5%8C%85%E4%B8%8E%20ECN%20%E4%B9%9F%E8%A6%81%E5%8F%8D%E5%BA%94%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E4%B8%8E%20CUBIC%20%E5%81%9A%E9%87%8F%E5%8C%96%E5%85%AC%E5%B9%B3%22%5D%0A%20%20end%0A%20%20C%20--%3E%20D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：若瓶颈缓冲深达 4 个 BDP，v1 的周期探测可能把队列一路推满：12.5 MB 的 BDP 配上 50 MB 缓冲，排队包要多等几个 RTT，交互流量的延迟从 100 ms 涨到几百 ms——这就是 v1 在深缓冲上仍会「膨胀」的量感，也是 v2 收着走的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PCC 等学习型 CC 全文。延迟型 Vegas/Swift 是下一课。后课默认：BBR 族是基于模型的 CC；v2/v3 针对公平与膨胀补丁。</p><p>与不可 ECN 的公网 CUBIC 混跑，结果仍依赖缓冲。</p><p>下一课<a href="/cs/delay-based-cc">延迟型拥塞 Vegas / Swift</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BBR 用 BW 与 RTT 估 BDP，而非纯 AIMD。</li><li>v2/v3 加强对丢/ECN 与公平的反应。</li><li>深缓冲与误码仍是模型边界。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Cardwell et al., 2016；BBRv2/v3 说明。</li></ul>',7))])}const f=A(p,[["render",C]]);export{u as __pageData,f as default};
